from abc import ABC, abstractmethod


class Character(ABC):
    """A character that may or may not still be alive."""

    @abstractmethod
    def __init__(self, first_name, is_alive=True):
        """Store the first name and life status."""
        self.first_name = first_name
        self.is_alive = is_alive

    def die(self):
        """Mark this character as no longer alive."""
        self.is_alive = False


class Stark(Character):
    """A member of House Stark."""

    def __init__(self, first_name, is_alive=True):
        """Build a Stark with a name and life status."""
        super().__init__(first_name, is_alive)
